INSERT INTO public.zsl_level_result (id_level,id_user,points,position,time,date_created) SELECT level_id,user_id,points,position,time,clock_timestamp() FROM unnest($1::integer[],$2::integer[],$3::integer[],$4::integer[],$5::real[]) AS input(level_id,user_id,points,position,time) ON CONFLICT(id_level,id_user) DO UPDATE SET points=excluded.points, position=excluded.position,time=excluded.time,date_updated=clock_timestamp()
